// SaveVehicleAsset is the resolver for the saveVehicleAsset field.
func (r *mutationResolver) SaveVehicleAsset(ctx context.Context, name string, licensePlate string, insuranceExpiry *time.Time, annualTestExpiry *time.Time, currentMileageKm *int, nextServiceMileageKm *int, notes *string) (*model.VehicleAsset, error) {
	actorID, hs, err := r.caller(ctx)
	if err != nil {
		return nil, err
	}

	existingAssets, _ := r.houseRepo().ListVehicleAssets(hs)
	var beforeAsset *dbmodels.VehicleAsset
	for i := range existingAssets {
		if strings.EqualFold(existingAssets[i].LicensePlate, licensePlate) {
			beforeAsset = &existingAssets[i]
			break
		}
	}
	beforeJSON := toJSON(beforeAsset)

	v := dbmodels.VehicleAsset{
		Name:             name,
		LicensePlate:     licensePlate,
		InsuranceExpiry:  insuranceExpiry,
		AnnualTestExpiry: annualTestExpiry,
	}
	if currentMileageKm != nil {
		v.CurrentMileageKm = *currentMileageKm
	}
	if nextServiceMileageKm != nil {
		v.NextServiceMileageKm = *nextServiceMileageKm
	}
	if notes != nil {
		v.Notes = *notes
	}

	action := "create"
	if beforeAsset != nil {
		v.ID = beforeAsset.ID
		action = "update"
		if err := r.houseRepo().UpdateVehicleAsset(hs, &v); err != nil {
			return nil, err
		}
	} else {
		if err := r.houseRepo().CreateVehicleAsset(hs, &v); err != nil {
			return nil, err
		}
	}

	r.publishEvent(ctx, events.MutationEvent{
		Topic:       "house",
		Action:      action,
		EntityType:  "vehicle_asset",
		EntityID:    uintToStr(v.ID),
		ActorUserID: actorID,
		HouseholdID: hs.HouseholdID(),
		FamilyGroup: hs.LegacyLabel(),
		BeforeJSON:  beforeJSON,
		AfterJSON:   toJSON(v),
		Summary:     fmt.Sprintf("Saved vehicle asset: %s (%s)", name, licensePlate),
		Timestamp:   time.Now(),
	})

	return toModelVehicleAsset(&v), nil
}

