// SaveAutomationRule is the resolver for the saveAutomationRule field.
func (r *mutationResolver) SaveAutomationRule(ctx context.Context, name string, triggerType string, triggerTopic string, conditionJSON string, actionInstruction string, isActive *bool) (*model.AutomationRule, error) {
	actorID, hs, err := r.caller(ctx)
	if err != nil {
		return nil, err
	}

	// BL-63: the same action rule as the chat tool: an instruction on a cron rule is a prompt:, one
	// on an event rule would do nothing and is refused.
	actionInstruction, err = automation.NormalizeAction(triggerType, actionInstruction)
	if err != nil {
		return nil, err
	}

	act := true
	if isActive != nil {
		act = *isActive
	}
	rule := dbmodels.AutomationRule{
		Name:              name,
		TriggerType:       triggerType,
		TriggerTopic:      triggerTopic,
		ConditionJSON:     conditionJSON,
		ActionInstruction: actionInstruction,
		IsActive:          act,
		UserID:            actorID,
		CreatedAt:         time.Now(),
	}

	if err := r.autoRepo().CreateAutomationRule(hs, &rule); err != nil {
		return nil, err
	}

	r.publishEvent(ctx, events.MutationEvent{
		Topic:       "automation",
		Action:      "create",
		EntityType:  "automation_rule",
		EntityID:    uintToStr(rule.ID),
		ActorUserID: actorID,
		HouseholdID: hs.HouseholdID(),
		FamilyGroup: hs.LegacyLabel(),
		BeforeJSON:  "",
		AfterJSON:   toJSON(rule),
		Summary:     fmt.Sprintf("Created automation rule: %s on %s/%s", name, triggerType, triggerTopic),
		Timestamp:   time.Now(),
	})

	return toModelAutomationRule(&rule), nil
}

// ToggleAutomationRule is the resolver for the toggleAutomationRule field.
func (r *mutationResolver) ToggleAutomationRule(ctx context.Context, id string, isActive bool) (*model.AutomationRule, error) {
	uID, err := toolutil.ParseID(id)
	if err != nil {
		return nil, fmt.Errorf("invalid automation rule id: %w", err)
	}

	actorID, hs, err := r.caller(ctx)
	if err != nil {
		return nil, err
	}

	// V4-30: the rule is read inside the caller's household only; a rule of another household is
	// refused, never reached.
	rule, err := r.autoRepo().GetAutomationRule(hs, uID)
	if err != nil || rule == nil {
		return nil, fmt.Errorf("permission denied: unauthorized access to automation rule")
	}

	beforeJSON := toJSON(rule)

	rule.IsActive = isActive
	if err := r.autoRepo().UpdateAutomationRule(hs, rule); err != nil {
		return nil, err
	}

	r.publishEvent(ctx, events.MutationEvent{
		Topic:       "automation",
		Action:      "update",
		EntityType:  "automation_rule",
		EntityID:    id,
		ActorUserID: actorID,
		HouseholdID: hs.HouseholdID(),
		FamilyGroup: hs.LegacyLabel(),
		BeforeJSON:  beforeJSON,
		AfterJSON:   toJSON(rule),
		Summary:     fmt.Sprintf("Toggled automation rule %s to %t", rule.Name, isActive),
		Timestamp:   time.Now(),
	})

	return toModelAutomationRule(rule), nil
}

// DeleteAutomationRule is the resolver for the deleteAutomationRule field.
func (r *mutationResolver) DeleteAutomationRule(ctx context.Context, id string) (bool, error) {
	uID, err := toolutil.ParseID(id)
	if err != nil {
		return false, fmt.Errorf("invalid automation rule id: %w", err)
	}

	actorID, hs, err := r.caller(ctx)
	if err != nil {
		return false, err
	}

	// V4-30: the rule is read inside the caller's household only; a rule of another household is
	// refused, never reached.
	rule, err := r.autoRepo().GetAutomationRule(hs, uID)
	if err != nil || rule == nil {
		return false, fmt.Errorf("permission denied: unauthorized access to automation rule")
	}

	beforeJSON := toJSON(rule)

	if err := r.autoRepo().DeleteAutomationRule(hs, uID); err != nil {
		return false, err
	}

	r.publishEvent(ctx, events.MutationEvent{
		Topic:       "automation",
		Action:      "delete",
		EntityType:  "automation_rule",
		EntityID:    id,
		ActorUserID: actorID,
		HouseholdID: hs.HouseholdID(),
		FamilyGroup: hs.LegacyLabel(),
		BeforeJSON:  beforeJSON,
		AfterJSON:   "",
		Summary:     fmt.Sprintf("Deleted automation rule: %s", rule.Name),
		Timestamp:   time.Now(),
	})

	return true, nil
}

// SaveUserPreference is the resolver for the saveUserPreference field.
func (r *mutationResolver) SaveUserPreference(ctx context.Context, userID string, preferredLanguage *string, tonePersona *string, defaultCurrency *string, quietHoursStart *string, quietHoursEnd *string, standingInstructions *string) (*model.UserPreference, error) {
	actorID, hs, err := r.caller(ctx)
	if err != nil {
		return nil, err
	}

	// V4-35: preferences are personal data, the caller's own only.
	targetUserID, err := r.resolveTargetUser(userID, hs)
	if err != nil {
		return nil, err
	}

	beforePref, _ := r.autoRepo().GetUserPreference(targetUserID)
	beforeJSON := toJSON(beforePref)

	pref := dbmodels.UserPreference{
		UserID:             targetUserID,
		PreferredLanguage:  "en",
		TonePersona:        "helpful",
		DefaultCurrency:    "USD",
		BriefingTopicsJSON: "[]",
		UpdatedAt:          time.Now(),
	}
	if beforePref != nil {
		pref = *beforePref
		pref.UpdatedAt = time.Now()
	}

	if preferredLanguage != nil {
		pref.PreferredLanguage = *preferredLanguage
	}
	if tonePersona != nil {
		pref.TonePersona = *tonePersona
	}
	if defaultCurrency != nil {
		pref.DefaultCurrency = *defaultCurrency
	}
	if quietHoursStart != nil {
		pref.QuietHoursStart = *quietHoursStart
	}
	if quietHoursEnd != nil {
		pref.QuietHoursEnd = *quietHoursEnd
	}
	// Enforced by the scheduler (V4-05), which ignores a window it cannot read: refuse one here,
	// when this request changes it (a window stored before V4-05 does not block other changes).
	if quietHoursStart != nil || quietHoursEnd != nil {
		if _, err := quiet.ParseWindow(pref.QuietHoursStart, pref.QuietHoursEnd); err != nil {
			return nil, fmt.Errorf("%w; use 24-hour times such as 22:00 and 07:30", err)
		}
	}
	if standingInstructions != nil {
		pref.StandingInstructions = *standingInstructions
	}

	if err := r.autoRepo().UpsertUserPreference(&pref); err != nil {
		return nil, err
	}

	r.publishEvent(ctx, events.MutationEvent{
		Topic:       "automation",
		Action:      "update",
		EntityType:  "user_preference",
		EntityID:    targetUserID,
		ActorUserID: actorID,
		HouseholdID: hs.HouseholdID(),
		FamilyGroup: hs.LegacyLabel(),
		BeforeJSON:  beforeJSON,
		AfterJSON:   toJSON(pref),
		Summary:     fmt.Sprintf("Updated preferences for user: %s", targetUserID),
		Timestamp:   time.Now(),
	})

	return toModelUserPreference(&pref), nil
}

